    public func getAllIngredients() -> [Ingredient] {
        return Array(masterIngredients.values)
    }

    public func getIngredientById(_ id: String) -> Ingredient? {
        return masterIngredients[id]
    }

    public func hasIngredient(_ id: String) -> Bool {
        return masterIngredients[id] != nil
    }

    public func getIngredientsByCategory(_ category: String) -> [Ingredient] {
        return masterIngredients.values.filter { $0.category == category }
    }

    public func getCrusts() -> [Ingredient] {
        return masterIngredients.values.filter { $0.category == "CRUST" }
    }

    public func getSauces() -> [Ingredient] {
        return masterIngredients.values.filter { $0.category == "SAUCE" }
    }

    public func getCheeses() -> [Ingredient] {
        return masterIngredients.values.filter { $0.category == "CHEESE" }
    }

    public func getToppings() -> [Ingredient] {
        return masterIngredients.values.filter { $0.category.hasPrefix("TOPPING") }
    }

    public func getIngredientsForRecipe(_ recipeId: String) -> [Ingredient] {
        return masterIngredients.values.filter { $0.applicableRecipes.contains(recipeId) }
    }
